/**
 * Signature v2 must match the node byte for byte: these are the shared
 * vectors generated by the Python implementation (tests/fixtures).
 */

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { canonicalQuery, signV2Hex } from "../shadowSigner";

interface VectorCase {
	name: string;
	method: string;
	path: string;
	query: string;
	body: string;
	canonical_query: string;
	signature: string;
}

const vectors = JSON.parse(
	readFileSync(join(__dirname, "../../../../../tests/fixtures/sig_v2_vectors.json"), "utf8"),
) as { secret: string; device_id: string; nonce: string; timestamp: number; cases: VectorCase[] };

describe("signature v2 shared vectors", () => {
	for (const c of vectors.cases) {
		it(c.name, () => {
			assert.equal(canonicalQuery(c.query), c.canonical_query);
			const pathWithQuery = c.query ? `${c.path}?${c.query}` : c.path;
			assert.equal(
				signV2Hex(
					vectors.secret,
					c.method,
					pathWithQuery,
					c.body,
					vectors.nonce,
					String(vectors.timestamp),
					vectors.device_id,
				),
				c.signature,
			);
		});
	}
});
